// Pruebas de lógica de citas (Node, sin navegador). Uso: node pruebas_citas.js ruta/a/app.js
const fs = require('fs');
const src = fs.readFileSync(process.argv[2] || './app.js', 'utf8');
const cut = (a, b) => src.slice(src.indexOf(a), src.indexOf(b));
const code = `
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let OPT = {lang:'es', dateFmt:'long', vanAll:false, ppChap:true}; const ex = () => OPT;
const normDoi = s => String(s || '').trim().replace(/^(https?:\\/\\/(dx\\.)?doi\\.org\\/|doi:\\s*)/i, '').trim().toLowerCase();
${cut('const TYPES', 'function NEWF')}
${cut('/* ===== Citas', '/* ===== Persistencia')}
return {TYPES, shows, NEWS, typeWarn, TYPE_WARN, STYLES, chiFn, isNum, yE, citeTxt, citeHtml, ini, isOrg, fdate, citeLink, pAuth, edLbl, numLbl, yearSuffixes, abcLetters, setOpt: o => OPT = {...OPT, ...o}, reset: () => OPT = {lang:'es', dateFmt:'long', vanAll:false, ppChap:true}};`;
const T = new Function(code)();
let fail = 0, n = 0;
const eq = (name, got, want) => { n++; if (got !== want) { fail++; console.log('FALLA', name, '\n  got :', JSON.stringify(got), '\n  want:', JSON.stringify(want)); } };
const A = (p, o) => T.STYLES.apa.fn(p, o), V = (p, o) => T.STYLES.vancouver.fn(p, o);
const base = {title:'T', authors:[], year:2020, type:'articulo', venue:'', doi:'', url:'', accessed:''};
const P = o => ({...base, ...o});

// Pruebas de aceptación de la guía (11.11) que se pueden hacer con los campos actuales
eq('11.11 #1 libro', T.citeTxt(A(P({type:'libro', authors:['Mankiw, N. Gregory'], year:2014, title:'Macroeconomía', venue:'Antoni Bosch'}))), 'Mankiw, N. G. (2014). Macroeconomía. Antoni Bosch.');
eq('11.11 #1 cursiva', A(P({type:'libro', authors:['Mankiw, N. Gregory'], year:2014, title:'Macroeconomía', venue:'Antoni Bosch'})), 'Mankiw, N. G. (2014). *Macroeconomía*. Antoni Bosch.');
eq('11.11 #3 entidad', A(P({type:'libro', authors:['World Tourism Organization'], year:2012, title:'Tourism and intangible cultural heritage', venue:'UNWTO'})), 'World Tourism Organization. (2012). *Tourism and intangible cultural heritage*. UNWTO.');
eq('entidad RAE', A(P({type:'libro', authors:['Real Academia Española'], year:2021, title:'Diccionario', venue:'Espasa'})), 'Real Academia Española. (2021). *Diccionario*. Espasa.');
eq('entidad siglas', A(P({type:'web', authors:['OMS'], year:2020, title:'Informe', venue:'OMS', url:'https://x.org'})), 'OMS. (2020). *Informe*. OMS. https://x.org');

// ejemplo del propio proyecto (artículo, 2 autores, DOI)
const ej = P({authors:['Pérez, Juan Carlos','Gómez, Lucía'], year:2021, title:'Ejemplo de título de paper', venue:'Revista de Ejemplo', doi:'10.1000/xyz123', url:'https://example.org/paper', accessed:'2026-10-20'});
eq('APA artículo', A(ej), 'Pérez, J. C. y Gómez, L. (2021). Ejemplo de título de paper. *Revista de Ejemplo*. https://doi.org/10.1000/xyz123');
eq('APA artículo en', A(ej, {lang:'en'}), 'Pérez, J. C., & Gómez, L. (2021). Ejemplo de título de paper. *Revista de Ejemplo*. https://doi.org/10.1000/xyz123');
eq('VAN artículo', V(ej), 'Pérez JC, Gómez L. Ejemplo de título de paper. Revista de Ejemplo [Internet]. 2021 [consultado 20 de octubre de 2026]. Disponible en: https://doi.org/10.1000/xyz123');
eq('VAN artículo en', V(ej, {lang:'en'}), 'Pérez JC, Gómez L. Ejemplo de título de paper. Revista de Ejemplo [Internet]. 2021 [cited 2026 Oct 20]. Available from: https://doi.org/10.1000/xyz123');
eq('VAN fecha dmy', V(ej, {dateFmt:'dmy'}).includes('[consultado 20-10-2026]'), true);
eq('VAN fecha iso', V(ej, {dateFmt:'iso'}).includes('[consultado 2026-10-20]'), true);
eq('VAN impreso (sin doi/url)', V(P({authors:['Pérez, Juan'], venue:'Rev Med', title:'Algo', year:2019})), 'Pérez J. Algo. Rev Med. 2019.');
eq('VAN online sin fecha consulta', V(P({authors:['Pérez, Juan'], venue:'Rev Med', title:'Algo', year:2019, url:'https://a.b'})), 'Pérez J. Algo. Rev Med [Internet]. 2019. Disponible en: https://a.b');

// conectores
eq('y/e ante I', A(P({authors:['Pérez, J.','Iglesias, M.'], title:'x', venue:'R'})).startsWith('Pérez, J. e Iglesias, M. (2020).'), true);
eq('e ante Hi', A(P({authors:['Pérez, J.','Hidalgo, M.'], title:'x', venue:'R'})).startsWith('Pérez, J. e Hidalgo, M.'), true);
eq('y ante Hie', A(P({authors:['Pérez, J.','Hierro, M.'], title:'x', venue:'R'})).startsWith('Pérez, J. y Hierro, M.'), true);
eq('e ante Í con tilde', A(P({authors:['Pérez, J.','Íñiguez, M.'], title:'x', venue:'R'})).startsWith('Pérez, J. e Íñiguez, M.'), true);
eq('3 autores en', A(P({authors:['Ruiz, Ana','Sanz, Bea','Toro, Cai'], title:'x', venue:'R'}), {lang:'en'}).startsWith('Ruiz, A., Sanz, B., & Toro, C. (2020).'), true);
eq('3 autores es b', A(P({authors:['Ruiz, Ana','Sanz, Bea','Toro, Cai'], title:'x', venue:'R'})).startsWith('Ruiz, A., Sanz, B. y Toro, C. (2020).'), true);

// sin autor / sin año
eq('sin autor libro', A(P({type:'libro', title:'El poema de Gilgamesh', year:2015, venue:'Anaya'})), '*El poema de Gilgamesh*. (2015). Anaya.');
eq('sin autor artículo', A(P({title:'Un artículo', year:2015, venue:'Revista X'})), 'Un artículo. (2015). *Revista X*.');
eq('sin autor con ?', A(P({title:'¿Qué es esto?', year:2015, venue:'Revista X'})), '¿Qué es esto? (2015). *Revista X*.');
