eq('sin año APA en', A(P({authors:['Ruiz, Ana'], year:'', title:'T', venue:'R'}), {lang:'en'}), 'Ruiz, A. (n.d.). T. *R*.');
eq('sin año VAN', V(P({authors:['Ruiz, Ana'], year:'', title:'T', venue:'R'})), 'Ruiz A. T. R.');
eq('sin año VAN online', V(P({authors:['Ruiz, Ana'], year:'', title:'T', venue:'R', url:'https://a.b', accessed:'2026-01-05'})), 'Ruiz A. T. R [Internet]. [consultado 5 de enero de 2026]. Disponible en: https://a.b');
eq('sin nada VAN', V(P({title:'T', year:''})), 'T.');

// guiones
eq('ini guion APA', A(P({authors:['Chung, Sae-Young'], title:'T', venue:'R'})), 'Chung, S.-Y. (2020). T. *R*.');
eq('ini guion VAN', V(P({authors:['Chung, Sae-Young'], title:'T', venue:'R', year:2020})), 'Chung SY. T. R. 2020.');
eq('ini ya abreviadas', T.ini('J.C.', 1), 'J. C.');
eq('ini S.-Y.', T.ini('S.-Y.', 1), 'S.-Y.');
eq('ini sin punto', T.ini('Juan Carlos'), 'JC');
eq('ini Nombre Apellido', A(P({authors:['Juan Pérez'], title:'T', venue:'R'})), 'Pérez, J. (2020). T. *R*.');

// 21+ autores y límite Vancouver
const many = n => Array.from({length:n}, (_, i) => `Ap${i+1}, N`);
const a21 = A(P({authors: many(21), title:'T', venue:'R'}));
eq('APA 21: 19 + . . . + último', a21.startsWith('Ap1, N., Ap2, N.') && a21.includes('Ap19, N., . . . Ap21, N. (2020).') && !a21.includes('Ap20,'), true);
eq('APA 20 autores', A(P({authors: many(20), title:'T', venue:'R'})).includes(' y Ap20, N. (2020).'), true);
eq('VAN 8 autores', V(P({authors: many(8), title:'T', venue:'R', year:2020})), 'Ap1 N, Ap2 N, Ap3 N, Ap4 N, Ap5 N, Ap6 N, et al. T. R. 2020.');
eq('VAN 8 autores todos', V(P({authors: many(8), title:'T', venue:'R', year:2020}), {vanAll:true}), 'Ap1 N, Ap2 N, Ap3 N, Ap4 N, Ap5 N, Ap6 N, Ap7 N, Ap8 N. T. R. 2020.');
eq('VAN 6 autores', V(P({authors: many(6), title:'T', venue:'R', year:2020})).startsWith('Ap1 N, Ap2 N, Ap3 N, Ap4 N, Ap5 N, Ap6 N. T.'), true);

// por tipo
eq('APA capítulo', A(P({type:'capitulo', authors:['Pedrós Esteban, A.'], year:2008, title:'Sostenibilidad ciudadana', venue:'Diálogos urbanos', url:'https://x.y'})), 'Pedrós Esteban, A. (2008). Sostenibilidad ciudadana. En *Diálogos urbanos*. https://x.y');
