eq('VAN libro', V(P({type:'libro', authors:['Bach-Faig, Anna'], year:2018, title:'La alimentación', venue:'Editorial UOC', url:'https://e.uoc/x', accessed:'2019-12-19'})), 'Bach-Faig A. La alimentación [Internet]. Editorial UOC; 2018 [consultado 19 de diciembre de 2019]. Disponible en: https://e.uoc/x');
