eq('VAN capítulo', V(P({type:'capitulo', authors:['Mouchawar, Judy'], year:2005, title:'Late-stage', venue:'Health care systems', url:'https://j.n', accessed:'2020-10-27'})), 'Mouchawar J. Late-stage. En: Health care systems [Internet]. 2005 [consultado 27 de octubre de 2020]. Disponible en: https://j.n');
