// heurística de entidad
for (const [s, w] of [['Real Academia Española', 1], ['World Health Organization', 1], ['OMS', 1], ['UNESCO', 1], ['Universidad de Chile', 1], ['Juan Pérez', 0], ['Press, William', 0], ['Pérez, Juan', 0], ['William Press', 0], ['Ana de la Torre', 0], ['Pérez', 0]])
  eq('isOrg ' + s, T.isOrg(s), !!w);
// fecha
eq('fdate mes inválido', T.fdate('2026-13-01', {}), '2026-13-01'); eq('fdate vacía', T.fdate('', {}), ''); eq('fdate texto libre', T.fdate('ayer', {}), 'ayer');

// F0.5: enlace y fecha de consulta por paper
const both = {...ej, doi:'10.1000/xyz123', url:'https://example.org/paper'};
eq('link auto = DOI', T.citeLink(both), 'https://doi.org/10.1000/xyz123');
